package com.erul.fixcore.editor;
import java.util.*;
import net.minecraft.client.gui.GuiScreen;
import net.minecraft.nbt.NBTTagCompound;
import betterquesting.api.questing.*;
import betterquesting.questing.*;
import betterquesting.api.properties.NativeProps;
import betterquesting.api2.client.gui.GuiScreenCanvas;
import betterquesting.api2.client.gui.controls.*;
import betterquesting.api2.client.gui.misc.GuiRectangle;
import betterquesting.api2.client.gui.panels.content.PanelTextBox;
import betterquesting.network.handlers.NetChapterEdit;
/** Chapter definitions are cloned. Connections modify the parent quest draft only. */
public final class ChapterWorkbench extends WorkbenchScreen {
 private UUID chapterId,selected;private QuestLine chapter;private NBTTagCompound baseline,pending;
 private int offsetX=180,offsetY=120,dragX,dragY,chapterPage;private boolean dragging;private long saveAt;private String status="拖动移动；Shift 点击为工作台当前任务添加前置。";
 private final Map<UUID,GuiRectangle> nodes=new LinkedHashMap<>();
 public ChapterWorkbench(GuiScreen p,UUID quest){super(p);selected=quest;useMargins(false);}
 private void label(int x,int y,int w,String s){addPanel(new PanelTextBox(new GuiRectangle(x,y,w,16),s));}
 private void btn(int x,int y,int w,String s,Runnable r){addPanel(new PanelButton(new GuiRectangle(x,y,w,18),0,s).setClickAction(b->{try{r.run();}catch(Exception e){status=e.getMessage();redraw();}}));}
 private boolean dirty(){return chapter!=null&&!baseline.equals(chapter.writeToNBT(new NBTTagCompound(),false));}
 private void redraw(){resetCanvas();initPanel();}
 private void load(UUID id){if(dirty())throw new IllegalStateException("请保存或放弃当前章节修改");chapterId=id;IQuestLine q=QuestLineDatabase.INSTANCE.get(id);baseline=q.writeToNBT(new NBTTagCompound(),false);chapter=new QuestLine();chapter.readFromNBT((NBTTagCompound)baseline.func_74737_b(),false);if(selected!=null&&chapter.containsKey(selected)){offsetX=220-chapter.get(selected).getPosX();offsetY=140-chapter.get(selected).getPosY();}redraw();}
 @Override public void initPanel(){super.initPanel();int w=getTransform().getWidth(),h=getTransform().getHeight();label(10,8,w-20,"§b章节布局 · 拖动节点 / 方向键平移 / Shift 点击添加前置");btn(10,28,65,"返回",()->{if(dirty())throw new IllegalStateException("章节尚未保存，请先保存或放弃");displayParent();});btn(80,28,85,"保存章节",()->{if(chapter==null)return;if(pending!=null)throw new IllegalStateException("等待服务端确认中");IQuestLine live=QuestLineDatabase.INSTANCE.get(chapterId);if(!baseline.equals(live.writeToNBT(new NBTTagCompound(),false)))throw new IllegalStateException("章节已变化，请放弃后重载");pending=chapter.writeToNBT(new NBTTagCompound(),false);NetChapterEdit.requestEdit(chapterId,chapter);saveAt=System.currentTimeMillis();status="保存中…";redraw();});btn(170,28,85,"放弃重载",()->{if(chapterId==null)return;UUID id=chapterId;chapter=null;pending=null;load(id);});btn(260,28,100,"任务加入章节",()->{UUID id=((QuestWorkbench)parent).currentQuestId();if(chapter!=null&&id!=null){if(chapter.containsKey(id))throw new IllegalArgumentException("任务已在当前章节");chapter.put(id,new QuestLineEntry(40-offsetX,100-offsetY));redraw();}});
 List<Map.Entry<UUID,IQuestLine>> list=new ArrayList<>(QuestLineDatabase.INSTANCE.entrySet());list.sort(Comparator.comparing(e->e.getValue().getProperty(NativeProps.NAME)));int count=Math.max(1,(h-142)/23);chapterPage=Math.max(0,Math.min(chapterPage,Math.max(0,(list.size()-1)/count)));for(int n=0;n<count&&chapterPage*count+n<list.size();n++){Map.Entry<UUID,IQuestLine> e=list.get(chapterPage*count+n);String text=e.getValue().getProperty(NativeProps.NAME);if(text.length()>15)text=text.substring(0,15)+"…";btn(10,62+n*23,145,text,()->load(e.getKey()));}btn(10,h-58,68,"上一页",()->{chapterPage--;redraw();});btn(82,h-58,73,"下一页",()->{chapterPage++;redraw();});label(10,h-27,w-20,status);
 nodes.clear();if(chapter==null){label(170,80,w-180,"选择章节；编辑后点击保存，服务端确认后才会显示成功。");return;}for(Map.Entry<UUID,IQuestLineEntry> e:chapter.entrySet()){IQuestLineEntry p=e.getValue();int nx=p.getPosX()+offsetX,ny=p.getPosY()+offsetY;if(nx<165||ny<60||nx>w-30||ny>h-70)continue;UUID id=e.getKey();GuiRectangle r=new GuiRectangle(nx,ny,Math.max(30,p.getSizeX()),Math.max(24,p.getSizeY()));nodes.put(id,r);IQuest q=QuestDatabase.INSTANCE.get(id);String name=q==null?"?":q.getProperty(NativeProps.NAME);if(name.length()>9)name=name.substring(0,9);addPanel(new PanelButton(r,0,(id.equals(selected)?"§a":"")+name));}}
 @Override public boolean onMouseClick(int x,int y,int b){if(b==0&&y>60&&x>165)for(Map.Entry<UUID,GuiRectangle> n:nodes.entrySet())if(n.getValue().contains(x,y)){if(GuiScreen.func_146272_n()){try{((QuestWorkbench)parent).addPrerequisite(n.getKey());status="前置已写入任务草稿，返回工作台保存";}catch(Exception e){status=e.getMessage();}redraw();return true;}selected=n.getKey();dragging=true;dragX=x;dragY=y;return true;}return super.onMouseClick(x,y,b);}
 @Override public void drawPanel(int x,int y,float t){if(pending!=null){IQuestLine live=QuestLineDatabase.INSTANCE.get(chapterId);if(live!=null&&pending.equals(live.writeToNBT(new NBTTagCompound(),false))){baseline=pending;pending=null;status="§a章节保存已由服务端确认";redraw();}else if(System.currentTimeMillis()-saveAt>15000){pending=null;status="保存未确认，请检查OP权限/网络";redraw();}}if(dragging&&chapter!=null&&selected!=null){IQuestLineEntry e=chapter.get(selected);if(e!=null){e.setPosition(e.getPosX()+x-dragX,e.getPosY()+y-dragY);GuiRectangle r=nodes.get(selected);if(r!=null){r.x+=x-dragX;r.y+=y-dragY;}dragX=x;dragY=y;}}for(Map.Entry<UUID,GuiRectangle> n:nodes.entrySet()){IQuest q=parent instanceof QuestWorkbench&&n.getKey().equals(((QuestWorkbench)parent).currentQuestId())?((QuestWorkbench)parent).currentDraft():QuestDatabase.INSTANCE.get(n.getKey());if(q==null)continue;for(UUID req:q.getRequirements()){GuiRectangle a=nodes.get(req),b=n.getValue();if(a!=null){int ax=a.x+a.w/2,ay=a.y+a.h/2,bx=b.x+b.w/2,by=b.y+b.h/2;int steps=Math.max(Math.abs(ax-bx),Math.abs(ay-by));for(int i=0;i<=steps;i++){int px=ax+(bx-ax)*i/Math.max(1,steps),py=ay+(by-ay)*i/Math.max(1,steps);GuiScreen.func_73734_a(px,py,px+1,py+1,0xff708ca8);}}}}super.drawPanel(x,y,t);}
 @Override public boolean onMouseRelease(int x,int y,int b){dragging=false;return super.onMouseRelease(x,y,b);}
 @Override public boolean onKeyTyped(char c,int k){int dx=k==203?20:k==205?-20:0,dy=k==200?20:k==208?-20:0;if(dx!=0||dy!=0){offsetX+=dx;offsetY+=dy;redraw();return true;}return super.onKeyTyped(c,k);}
 @Override public void func_73869_a(char c,int k){if(k==1){if(dirty()){status="章节尚未保存，请先保存或放弃";redraw();}else displayParent();return;}super.func_73869_a(c,k);}
}
